// ============================================================
// RUSSIAN-DATA.JS — данные для Помощника
// ============================================================

window.RU_DATA = {
  dictionary: new Set(),
  loaded: false,
  loadPromise: null
};

// ============================================================
// ЗАГРУЗКА СЛОВАРЯ
// ============================================================
window.RU_DATA.load = function() {
  if (this.loadPromise) return this.loadPromise;
  var self = this;
  this.loadPromise = fetch('russian_nouns.txt')
    .then(function(r) { return r.text(); })
    .then(function(text) {
      var words = text.split(/\r?\n/);
      words.forEach(function(w) {
        var clean = w.trim().toLowerCase();
        if (clean) self.dictionary.add(clean);
      });
      self.loaded = true;
      console.log('[Помощник] Словарь загружен:', self.dictionary.size, 'слов');
      return self.dictionary.size;
    })
    .catch(function(e) {
      console.warn('[Помощник] Словарь не загружен, использую базовый:', e);
      self.loadFallback();
      return self.dictionary.size;
    });
  return this.loadPromise;
};

