// Определение части речи
window.RU_DATA.getPartOfSpeech = function(word) {
  var w = word.toLowerCase().replace(/[^а-яё]/g, '');
  if (!w) return '—';
  if (this.PRONOUNS.indexOf(w) !== -1) return 'Местоимение';
  if (this.PREPOSITIONS.indexOf(w) !== -1) return 'Предлог';
  if (this.CONJUNCTIONS.indexOf(w) !== -1) return 'Союз';
  if (this.PARTICLES.indexOf(w) !== -1) return 'Частица';
  if (this.ADVERBS.indexOf(w) !== -1) return 'Наречие';
  // Числительное
  if (/^(один|одна|одно|два|две|три|четыре|пять|шесть|семь|восемь|девять|десять|ноль|нуль|сотня|тысяча|миллион|первый|второй|третий|четвёртый|пятый)$/.test(w)) return 'Числительное';
  // Глагол
  if (/(ть|ться|тся|шь|шься|л|ла|ло|ли|ет|ит|ут|ют|ат|ят|ем|им|ете|ите)$/.test(w) && w.length > 3) {
    if (/(ать|ять|еть|ить|ыть|уть)$/.test(w)) return 'Глагол (инфинитив)';
    return 'Глагол';
  }
  // Прилагательное
  if (/(ый|ий|ой|ая|яя|ое|ее|ые|ие|ого|его|ому|ему|ым|им|ыми|ими)$/.test(w)) return 'Прилагательное';
  // Существительное (по умолчанию)
  return 'Существительное';
};

// Определение рода
window.RU_DATA.getGender = function(word) {
  var w = word.toLowerCase().replace(/[^а-яё]/g, '');
  if (!w) return '—';
  // Женский — оканчивается на -а, -я, -ь (иногда)
  if (/(а|я)$/.test(w) && !/(мя|время|имя|пламя|знамя|племя|семя|стремя|темя|бремя)$/.test(w)) return 'Женский';
  // Средний — на -о, -е, -мя
  if (/(о|е|мя)$/.test(w)) return 'Средний';
  // Мужской — на согласную, -й, -ь (иногда)
  if (/[бвгджзйклмнпрстфхцчшщ]$/.test(w)) return 'Мужской';
  if (/ь$/.test(w)) return 'Мужской/Женский (по контексту)';
  return '—';
};

// Определение числа
window.RU_DATA.getNumber = function(word) {
  var w = word.toLowerCase().replace(/[^а-яё]/g, '');
  // Множественное — характерные окончания
  if (/(ы|и|а|я)$/.test(w) && w.length > 3) {
    // Проверяем, не singular ли это
    if (/(а|я)$/.test(w)) return 'Единственное';
  }
  return 'Единственное';
};

// Определение падежа (упрощённо)
window.RU_DATA.getCase = function(word) {
  var w = word.toLowerCase();
  if (/(ой|ей|ом|ем|ым|им|ыми|ими)$/.test(w)) return 'Творительный';
  if (/(а|я|ы|и|ов|ев|ёв)$/.test(w)) return 'Родительный';
  if (/(у|ю|ам|ям)$/.test(w)) return 'Дательный';
  if (/(а|я|о|е|ы|и)$/.test(w)) return 'Именительный/Винительный';
  return 'Именительный';
};

// Определение склонения
window.RU_DATA.getDeclension = function(word) {
  var w = word.toLowerCase();
  var gender = this.getGender(w);
  if (gender === 'Женский' && /(а|я)$/.test(w)) return '1-е склонение';
  if (gender === 'Мужской' && /[бвгджзйклмнпрстфхцчшщ]$/.test(w)) return '2-е склонение';
  if (gender === 'Средний' && /(о|е)$/.test(w)) return '2-е склонение';
  if (gender === 'Женский' && /ь$/.test(w)) return '3-е склонение';
  return '—';
};

// Определение вида глагола
window.RU_DATA.getVerbAspect = function(word) {
  var w = word.toLowerCase();
  // Совершенный — есть приставка и нет суффикса -ыва/-ива
  if (/^(по|при|у|вы|за|на|про|пере|из|с|от|до|раз|рас)/.test(w) && !/(ыва|ива)/.test(w)) return 'Совершенный';
  return 'Несовершенный';
};

// Определение спряжения
window.RU_DATA.getConjugation = function(word) {
  var w = word.toLowerCase();
  if (/(ить|еть|ать|ять)$/.test(w)) {
    if (/ить$/.test(w)) return 'II спряжение';
    return 'I спряжение';
  }
  return '—';
};

// Звонкий/глухой
window.RU_DATA.getVoiced = function(letter) {
  var voiced = 'бвгдзжлмнрй';
  var voiceless = 'пфктшсхцчщ';
  var l = letter.toLowerCase();
  if (voiced.indexOf(l) !== -1) return 'звонкий';
  if (voiceless.indexOf(l) !== -1) return 'глухой';
  return '—';
};

// Мягкий/твёрдый
window.RU_DATA.getSoftness = function(letter) {
  var soft = 'йчщ';
  var alwaysHard = 'жшц';
  var l = letter.toLowerCase();
  if (soft.indexOf(l) !== -1) return 'мягкий';
  if (alwaysHard.indexOf(l) !== -1) return 'твёрдый';
  return 'может быть мягким/твёрдым';
};

// Парный/непарный
window.RU_DATA.getPair = function(letter) {
  var pairs = {
    'б':'п','п':'б','в':'ф','ф':'в','г':'к','к':'г','д':'т','т':'д',
    'ж':'ш','ш':'ж','з':'с','с':'з'
  };
  var l = letter.toLowerCase();
  if (pairs[l]) return 'парный (со звуком ' + pairs[l] + ')';
  return 'непарный';
};

// Разбор по морфемам (упрощённый)
window.RU_DATA.getMorphemes = function(word) {
  var w = word.toLowerCase().replace(/[^а-яё]/g, '');
  var result = { prefix: '', root: '', suffix: '', ending: '', base: '' };
  if (w.length < 3) { result.root = w; result.base = w; return result; }

  // Окончание
  var ending = '';
  var endings = ['ами','ями','ах','ях','ов','ев','ёв','ой','ей','ом','ем','ым','им','ыми','ими','ого','его','ому','ему','ая','яя','ое','ее','ые','ие','ый','ий','а','я','о','е','ы','и','у','ю','ь'];
  for (var i = 0; i < endings.length; i++) {
    if (w.endsWith(endings[i]) && w.length - endings[i].length >= 2) {
      ending = endings[i];
      break;
    }
  }
  var withoutEnding = ending ? w.slice(0, -ending.length) : w;
  result.ending = ending;

  // Приставка
  var prefix = '';
  for (var j = 0; j < this.PREFIXES.length; j++) {
    if (withoutEnding.startsWith(this.PREFIXES[j]) && withoutEnding.length - this.PREFIXES[j].length >= 3) {
      prefix = this.PREFIXES[j];
      break;
    }
  }
  result.prefix = prefix;
  var withoutPrefix = prefix ? withoutEnding.slice(prefix.length) : withoutEnding;

  // Суффикс
  var suffix = '';
  for (var k = 0; k < this.SUFFIXES.length; k++) {
    if (withoutPrefix.endsWith(this.SUFFIXES[k]) && withoutPrefix.length - this.SUFFIXES[k].length >= 3) {
      suffix = this.SUFFIXES[k];
      break;
    }
  }
  result.suffix = suffix;
  result.root = suffix ? withoutPrefix.slice(0, -suffix.length) : withoutPrefix;
  result.base = (prefix || '') + result.root + (suffix || '');
  return result;
};

// Фонетический разбор
window.RU_DATA.getPhonetic = function(word) {
  var vowels = 'аеёиоуыэюя';
  var w = word.toLowerCase().replace(/[^а-яё]/g, '');
  var sounds = [];
  for (var i = 0; i < w.length; i++) {
    var l = w[i];
    var s = { letter: l, sound: l, type: '', voiced: '', soft: '', pair: '' };
    if (vowels.indexOf(l) !== -1) {
      s.type = 'гласный';
      s.sound = l;
    } else if (l === 'ь' || l === 'ъ') {
      s.type = 'не обозначает звука';
      s.sound = '—';
    } else {
      s.type = 'согласный';
      s.voiced = this.getVoiced(l);
      s.soft = this.getSoftness(l);
      s.pair = this.getPair(l);
    }
    sounds.push(s);
  }
  return sounds;
};

// Проверка слова по словарю
window.RU_DATA.checkWord = function(word) {
  var clean = word.toLowerCase().replace(/[^а-яё]/g, '');
  if (!clean || clean.length < 2) return { correct: true };
  if (this.dictionary.has(clean)) return { correct: true };
  // Ищем похожие
  var suggestions = [];
  var self = this;
  var limit = 3000; // ограничиваем поиск для скорости
  var count = 0;
  this.dictionary.forEach(function(dictWord) {
    if (count++ > limit) return;
    if (Math.abs(dictWord.length - clean.length) > 2) return;
    var dist = levenshtein(clean, dictWord);
    if (dist <= 2 && dist > 0) suggestions.push({ word: dictWord, dist: dist });
  });
  suggestions.sort(function(a, b) { return a.dist - b.dist; });
  return {
    correct: false,
    suggestions: suggestions.slice(0, 3).map(function(x) { return x.word; })
  };
};

// Левенштейн
function levenshtein(a, b) {
  var m = a.length, n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;
  var prev = [], curr = [];
  for (var j = 0; j <= n; j++) prev[j] = j;
  for (var i = 1; i <= m; i++) {
    curr[0] = i;
    for (var j = 1; j <= n; j++) {
      var cost = a[i-1] === b[j-1] ? 0 : 1;
      curr[j] = Math.min(prev[j] + 1, curr[j-1] + 1, prev[j-1] + cost);
    }
    prev = curr.slice();
  }
  return prev[n];
}

